using Cashier.Core;using Cashier.Core.Services;using ClosedXML.Excel;
if(args.Length!=1||Directory.Exists(args[0]))throw new Exception("New isolated directory required");
AppSession.Db=new Database(args[0]);AppSession.Db.EnsureCreated();var admin=new AuthService().Login("admin","admin888");AppSession.Current=admin;
int checks=0,fail=0;void Check(string n,bool ok){checks++;if(!ok){fail++;Console.WriteLine("FAIL | "+n);}}void Reject(string n,Action a){try{a();Check(n,false);}catch(AppException){Check(n,true);}}
long Scalar(string sql){using var c=AppSession.Db.Open();return new SqlCmd(c,sql).Long();}void Sql(string sql){using var c=AppSession.Db.Open();new SqlCmd(c,sql).Exec();}
var customer=MasterDataService.SavePartner(new Partner{Code="0001",Name="客户",Kind="customer"});var supplier=MasterDataService.SavePartner(new Partner{Code="0002",Name="供应商",Kind="supplier"});var funds=VoucherService.TotalFunds();
var svc=new InvoiceService();
string File(InvoiceKind kind,string name,IEnumerable<Line> lines){var path=Path.Combine(args[0],name+".xlsx");ExcelService.CreateInvoiceTemplate(kind,path);using(var w=new XLWorkbook(path)){var s=w.Worksheet(1);int r=2;foreach(var x in lines){s.Cell(r,1).Value=x.Date;s.Cell(r,2).Value="普通";s.Cell(r,3).Value=x.No;s.Cell(r,4).Value="000012";s.Cell(r,5).Value=x.Partner;s.Cell(r,6).Value=x.Gross/100m;s.Cell(r,7).Value=x.Rate/100m;s.Cell(r,8).Value=x.Net/100m;s.Cell(r,9).Value=x.Tax/100m;s.Cell(r,11).Value=x.Original;r++;}w.Save();}return path;}
Line Blue(string no,string p="KH-0001")=>new(no,p,11300,10001,1299,1300,"2024-01-10","");Line Red(string no,string original,string p="KH-0001")=>new(no,p,-1130,-1000,-130,1300,"2024-02-10",original);
foreach(var kind in new[]{InvoiceKind.Out,InvoiceKind.In}){
 string p=kind==InvoiceKind.Out?"KH-0001":"GYS-0001";string prefix=kind==InvoiceKind.Out?"O":"I";
 var file=File(kind,prefix+"-batch",new[]{Red(prefix+"-red",prefix+"-blue",p),Blue(prefix+"-blue",p)});
 var preview=ExcelService.PreviewInvoiceImport(kind,file);Check("red before blue preview "+kind,preview.OkCount==2&&preview.ErrorCount==0);Check("blue red same file committed "+kind,ExcelService.CommitInvoiceImport(preview)==2);
 var blue=svc.List(kind,prefix+"-blue",null,null,null,false).Single();var red=svc.List(kind,prefix+"-red",null,null,null,false).Single();Check("red resolved actual positive ID "+kind,red.OriginalInvoiceId==blue.Id&&red.OriginalInvoiceId>0&&red.GrossCents==-1130);Check("manual net tax preserved "+kind,blue.NetCents==10001&&blue.TaxCents==1299&&blue.InvoiceCode=="000012");
 var repeat=ExcelService.PreviewInvoiceImport(kind,file);Check("repeat entire file skipped "+kind,repeat.DuplicateCount==2&&repeat.OkCount==0);Reject("no duplicate batch write "+kind,()=>ExcelService.CommitInvoiceImport(repeat));
}
var duplicate=File(InvoiceKind.Out,"leading-zero",new[]{Blue("00000000001"),Blue("00000000001"),Blue("BAD","UNKNOWN"),new Line("SUM","KH-0001",11300,10000,1000,1300,"2024-01-01","")});
var dup=ExcelService.PreviewInvoiceImport(InvoiceKind.Out,duplicate);Check("mixed valid duplicate and error rows",dup.OkCount==1&&dup.DuplicateCount==1&&dup.ErrorCount==2);Check("valid subset import explicit preview",ExcelService.CommitInvoiceImport(dup)==1);
var checkFile=Path.Combine(args[0],"校验结果.xlsx");ExcelService.ExportInvoiceValidation(dup,checkFile);using(var w=new XLWorkbook(checkFile)){Check("validation export retains leading zeros",w.Worksheet(1).Cell(2,3).GetString()=="00000000001"&&w.Worksheet(1).Cell(2,3).DataType==XLDataType.Text);Check("validation export identifies exact error row",w.Worksheet(1).Cell(4,15).GetString().Contains("UNKNOWN"));}
var badRef=File(InvoiceKind.Out,"red-guards",new[]{Red("WRONGPARTNER","I-blue"),Red("MISSING","missing"),Red("EARLY","O-blue") with{Date="2023-01-01"},Red("WRONGRATE","O-blue") with{Rate=600},Blue("BLUE-ORIG") with{Original="O-blue"},Red("OVER","O-blue") with{Gross=-100000,Net=-90000,Tax=-10000}});
Check("preview original partner date rate quota guards",ExcelService.PreviewInvoiceImport(InvoiceKind.Out,badRef).ErrorCount==6);
var over=File(InvoiceKind.Out,"cumulative-red",new[]{Blue("TOTAL-BLUE"),Red("TOTAL-RED1","TOTAL-BLUE") with{Gross=-8000,Net=-7080,Tax=-920},Red("TOTAL-RED2","TOTAL-BLUE") with{Gross=-4000,Net=-3540,Tax=-460}});
var overp=ExcelService.PreviewInvoiceImport(InvoiceKind.Out,over);Check("cumulative red quota counted across batch",overp.ErrorCount==1&&overp.Rows.Last().Error!.Contains("累计"));
var rollback=File(InvoiceKind.Out,"rollback",new[]{Blue("RB1"),Blue("RB2") with{Date="2024-03-10"}});var rp=ExcelService.PreviewInvoiceImport(InvoiceKind.Out,rollback);var before=Scalar("SELECT COUNT(*) FROM invoices");PeriodService.Close("202403");Reject("closed period after preview rolls back",()=>ExcelService.CommitInvoiceImport(rp));Check("rollback leaves no first-row invoice",Scalar("SELECT COUNT(*) FROM invoices")==before);PeriodService.Reopen("202403","测试");
var audit=File(InvoiceKind.Out,"audit-failure",new[]{Blue("AUD1"),Blue("AUD2")});var ap=ExcelService.PreviewInvoiceImport(InvoiceKind.Out,audit);long beforeLog=Scalar("SELECT COUNT(*) FROM audit_log"),beforeBatch=Scalar("SELECT COUNT(*) FROM import_batches");
Sql("CREATE TRIGGER fail_inv_audit BEFORE INSERT ON audit_log WHEN NEW.entity='invoice' AND NEW.doc_no='AUD2' BEGIN SELECT RAISE(ABORT,'test audit'); END;");Reject("audit error rolls back entire invoice batch",()=>ExcelService.CommitInvoiceImport(ap));Sql("DROP TRIGGER fail_inv_audit;");Check("no invoice audit or batch partial write",Scalar("SELECT COUNT(*) FROM invoices")==before&&Scalar("SELECT COUNT(*) FROM audit_log")==beforeLog&&Scalar("SELECT COUNT(*) FROM import_batches")==beforeBatch);
var active=ExcelService.PreviewInvoiceImport(InvoiceKind.Out,audit);var c=MasterDataService.GetPartner(customer)!;c.IsActive=false;MasterDataService.SavePartner(c);Reject("deactivated after preview rejected",()=>ExcelService.CommitInvoiceImport(active));c.IsActive=true;MasterDataService.SavePartner(c);
var tamper=ExcelService.PreviewInvoiceImport(InvoiceKind.Out,audit);tamper.Rows[0].Invoice!.NetCents=1;Reject("modified preview cannot alter saved values",()=>ExcelService.CommitInvoiceImport(tamper));
var formula=File(InvoiceKind.Out,"formula",new[]{Blue("FORMULA")});using(var w=new XLWorkbook(formula)){w.Worksheet(1).Cell(2,8).FormulaA1="UNSUPPORTED_FUNC(100)";w.Save();}Check("formula rejected instead of stale calculated value",ExcelService.PreviewInvoiceImport(InvoiceKind.Out,formula).ErrorCount==1);
var wrongkind=File(InvoiceKind.Out,"wrong-kind",new[]{Blue("WRONG-KIND","GYS-0001")});Check("customer supplier direction guard",ExcelService.PreviewInvoiceImport(InvoiceKind.Out,wrongkind).ErrorCount==1);
var replaceFile=File(InvoiceKind.Out,"original-replaced",new[]{Red("REPLACED","REPLACE-BLUE")});var orig=svc.Save(new Invoice{Kind=InvoiceKind.Out,InvoiceType="普通",InvoiceNo="REPLACE-BLUE",PartnerId=customer,RegDate="2024-01-01",GrossCents=11300,NetCents=10000,TaxCents=1300,RateBp=1300});var replacePreview=ExcelService.PreviewInvoiceImport(InvoiceKind.Out,replaceFile);svc.Void(orig,"模拟预览后原票变化");svc.Save(new Invoice{Kind=InvoiceKind.Out,InvoiceType="普通",InvoiceNo="REPLACE-BLUE",PartnerId=customer,RegDate="2024-01-01",GrossCents=11300,NetCents=10000,TaxCents=1300,RateBp=1300});Reject("replaced original ID not silently rebound",()=>ExcelService.CommitInvoiceImport(replacePreview));
foreach(var kind in new[]{InvoiceKind.Out,InvoiceKind.In}){
 string p=kind==InvoiceKind.Out?"KH-0001":"GYS-0001";var file=File(kind,"large-"+kind,Enumerable.Range(0,1000).Select(i=>Blue("M-"+kind+"-"+i.ToString("D5"),p)));var preview=ExcelService.PreviewInvoiceImport(kind,file);Check("1000 invoices preview "+kind,preview.OkCount==1000&&preview.ErrorCount==0);Check("1000 invoices commit "+kind,ExcelService.CommitInvoiceImport(preview)==1000);var imported=svc.List(kind,"M-"+kind,null,null,null,false);Check("bulk totals and every partner ID "+kind,imported.Count==1000&&imported.All(x=>x.PartnerId==(kind==InvoiceKind.Out?customer:supplier))&&imported.Sum(x=>x.GrossCents)==11300000&&imported.Sum(x=>x.TaxCents)==1299000);
}
AppSession.Current=new User{Id=admin.Id,Role=UserRole.Viewer};Reject("viewer cannot preview",()=>ExcelService.PreviewInvoiceImport(InvoiceKind.Out,audit));Reject("viewer cannot commit",()=>ExcelService.CommitInvoiceImport(ap));AppSession.Current=admin;
Check("batch invoice registration does not move funds",VoucherService.TotalFunds()==funds);Check("current database version",AppSession.Db.GetUserVersion()==Database.CurrentVersion);Check("foreign keys",Scalar("SELECT COUNT(*) FROM pragma_foreign_key_check")==0);
Console.WriteLine($"RESULT checks={checks} failures={fail}");return fail==0?0:1;
record Line(string No,string Partner,long Gross,long Net,long Tax,int Rate,string Date,string Original);


